import Image from "next/image";
import Link from "next/link";

export default function Hero() {
  return (
    <section className="relative overflow-hidden bg-[#F8F4EC] pt-36 pb-24">

      {/* Map Texture */}
      <div
        className="absolute inset-0 opacity-[0.08]"
        style={{
          backgroundImage: "url('/images/textures/map-texture.png')",
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      />

      {/* Left Compass */}
      <Image
        src="/images/illustrations/compass-bg.png"
        alt=""
        width={380}
        height={380}
        className="absolute left-[-120px] top-16 opacity-[0.08] pointer-events-none select-none"
      />

      {/* Right Mountains */}
      <Image
        src="/images/illustrations/mountains.png"
        alt=""
        width={430}
        height={650}
        className="absolute right-0 top-28 opacity-[0.22] pointer-events-none select-none"
      />

      {/* Travel Path */}
      <svg
        className="absolute inset-0 w-full h-full pointer-events-none"
        viewBox="0 0 1600 900"
        preserveAspectRatio="none"
      >
        <path
          d="M0 250
             C180 250 160 520 40 560
             M1600 110
             C1460 110 1400 240 1460 320
             C1520 420 1580 430 1600 430"
          fill="none"
          stroke="#C89D4A"
          strokeWidth="2"
          strokeDasharray="6 12"
          opacity=".55"
        />
      </svg>

      {/* Hero Content */}
      <div className="relative max-w-5xl mx-auto px-8 text-center">

        {/* Logo */}
        <Image
          src="/images/brand/fio-logo.png"
          alt="Figuring It Out"
          width={240}
          height={240}
          priority
          className="mx-auto mb-6"
        />

        {/* Title */}
        <h1
          className="font-serif text-[#214534] leading-none tracking-[0.05em]"
          style={{
            fontSize: "clamp(4rem,8vw,6rem)",
          }}
        >
          FIGURING IT OUT
          <span className="align-top text-lg ml-1">™</span>
        </h1>

        {/* Divider */}
        <div className="flex items-center justify-center gap-4 mt-6 mb-8">
          <div className="w-20 h-px bg-[#C89D4A]" />
          <div className="w-3 h-3 rotate-45 bg-[#C89D4A]" />
          <div className="w-20 h-px bg-[#C89D4A]" />
        </div>

        {/* Headline */}
        <h2 className="font-serif text-[#214534] text-5xl leading-tight">
          Choosing to keep moving
        </h2>

        <h3 className="font-serif italic text-[#C89D4A] text-5xl mt-1">
          when life doesn't make sense.
        </h3>

        {/* Subheading */}
        <p className="mt-8 text-3xl font-serif text-[#263126]">
          One philosophy. Two paths.
        </p>

        {/* Description */}
        <p className="mt-8 max-w-3xl mx-auto text-lg leading-9 text-[#4F4F4F]">
          Figuring It Out™ is the lifelong practice of moving through
          uncertainty with curiosity, courage, and hope—trusting that
          understanding and confidence grow with every step.
        </p>

        {/* CTA */}
        <Link
          href="#choose-path"
          className="inline-flex mt-12 items-center rounded-lg bg-[#214534] px-10 py-4
          text-white uppercase tracking-[.2em] text-sm font-semibold
          transition-all duration-300
          hover:bg-[#2D5B43]
          hover:-translate-y-1
          hover:shadow-xl"
        >
          Begin Your Journey ↓
        </Link>

      </div>

    </section>
  );
}